-- Lane A figures for None: generated by build_load_sql.py, do not hand-edit.
-- 3 figures across 2 families, from scripts/lane-a-pilot/specs.json.
-- Entries are resolved by natural key, so this file is portable between environments.

begin;

-- 1. The renderer families this batch INTRODUCES (DECISION-0115: a row, not a CHECK).
-- Reused without introducing: none
insert into app.figure_families (family_key, title, summary, renderer_note)
values ('circuit_symbols', 'Circuit schematic symbol key', 'The standard schematic symbols drawn as a legend sheet rather than as a working circuit, each in its own cell with its name beneath it. A variable element is the standard symbol with a diagonal strikethrough arrow across it, which is a notation rather than a separate component.', 'scripts/lane-a-pilot/render.py; the app''s figure renderer')
on conflict (family_key) do nothing;
insert into app.figure_families (family_key, title, summary, renderer_note)
values ('field_map', 'Electric field and equipotential maps', 'Field lines traced by stepping along the field COMPUTED from point charges, sample field vectors, and isolines of potential. Field lines and isolines are complementary readings of one field, so they are one family: lines never cross, they run from positive to negative, and an isoline meets the field at a right angle because the geometry is computed rather than sketched.', 'scripts/lane-a-pilot/render.py; the app''s figure renderer')
on conflict (family_key) do nothing;

-- 2. The figures.
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('phys-electric-field-map', 'ap_physics_2', 'field_map', 'Electric field of two opposite charges', 'Field lines and vectors', 'Lines leave the positive charge and arrive at the negative one', 'A dipole: equal and opposite charges. Field lines run from the positive charge to the negative one, and sample field vectors show the field''s direction and relative strength at particular points. The lines crowd where the field is strong.', 'A map of the electric field around two equal and opposite point charges, the positive one on the left and the negative one on the right. Curved field lines leave the positive charge in every direction and curve round to arrive at the negative charge, each carrying one arrowhead showing which way the field points. Separate straight arrows at sample points show the field vector there: longer where the field is stronger, and always tangent to the line through that point. The lines are packed closely near the charges, where the field is strong, and spread far apart at the edges, where it is weak. No two lines ever cross, because the field has only one direction at each point. Illustrative data.', '', '', 'Lines never cross: the field has one direction at each point.', true, null, '["Field vector", "Field line", "Source charges"]'::jsonb, '{"charges": [{"q": 1.0, "x": 0.28, "y": 0.5}, {"q": -1.0, "x": 0.72, "y": 0.5}], "field_lines": true, "lines_per_unit_charge": 10, "vector_points": [[0.0833, 0.0833], [0.25, 0.0833], [0.4167, 0.0833], [0.5833, 0.0833], [0.75, 0.0833], [0.9167, 0.0833], [0.0833, 0.25], [0.25, 0.25], [0.4167, 0.25], [0.5833, 0.25], [0.75, 0.25], [0.9167, 0.25], [0.0833, 0.4167], [0.4167, 0.4167], [0.5833, 0.4167], [0.9167, 0.4167], [0.0833, 0.5833], [0.4167, 0.5833], [0.5833, 0.5833], [0.9167, 0.5833], [0.0833, 0.75], [0.25, 0.75], [0.4167, 0.75], [0.5833, 0.75], [0.75, 0.75], [0.9167, 0.75], [0.0833, 0.9167], [0.25, 0.9167], [0.4167, 0.9167], [0.5833, 0.9167], [0.75, 0.9167], [0.9167, 0.9167]], "unit_note": "arrows are sample field vectors; grey curves are field lines", "dipole_check": true}'::jsonb, null, null, 'published', 'cramapple-authored; batch=phys-electric,phys2-equipotential,phys2-circuit-figures-2026-10-11', now())
on conflict (figure_id) do nothing;
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('phys2-equipotential-map', 'ap_physics_2', 'field_map', 'Equipotentials and field vectors around a point charge', 'Isolines cross at 90°', 'The field meets every isoline at a right angle', 'A single positive charge. The dashed circles are isolines, each one a set of points at the same potential; the arrows are field vectors. Each arrow points straight outwards, at right angles to the isoline it crosses, and towards lower potential.', 'A map around a single positive point charge. Four dashed circles centred on the charge are isolines of electric potential: every point on one circle is at the same potential, and the potential falls as the circles get larger. Straight arrows placed between the circles are electric field vectors. Each arrow points directly away from the charge, so where it meets an isoline it crosses at a right angle, and it points towards lower potential. Because no arrow has any component along a circle, moving a charge around an isoline takes no work at all. The arrows are longer close to the charge, where the field is stronger. Illustrative data.', '', '', 'No field component runs along an isoline, so no work is done moving along one.', true, null, '["Isolines", "Isolines vs. field vectors", "Field direction", "Field along an isoline"]'::jsonb, '{"charges": [{"q": 1.0, "x": 0.5, "y": 0.5}], "isoline_radii": [0.14, 0.24, 0.34, 0.44], "vector_points": [[0.69, 0.5], [0.6344, 0.6344], [0.5, 0.69], [0.3656, 0.6344], [0.31, 0.5], [0.3656, 0.3656], [0.5, 0.31], [0.6344, 0.3656], [0.79, 0.5], [0.7051, 0.7051], [0.5, 0.79], [0.2949, 0.7051], [0.21, 0.5], [0.2949, 0.2949], [0.5, 0.21], [0.7051, 0.2949], [0.89, 0.5], [0.7758, 0.7758], [0.5, 0.89], [0.2242, 0.7758], [0.11, 0.5], [0.2242, 0.2242], [0.5, 0.11], [0.7758, 0.2242]], "unit_note": "dashed circles are isolines; arrows are field vectors", "isoline_check": true}'::jsonb, null, null, 'published', 'cramapple-authored; batch=phys-electric,phys2-equipotential,phys2-circuit-figures-2026-10-11', now())
on conflict (figure_id) do nothing;
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('phys2-circuit-symbols', 'ap_physics_2', 'circuit_symbols', 'Circuit schematic symbols', 'Schematic symbols', 'The standard symbols, and what a diagonal arrow across one means', 'The eight symbols used to draw circuit schematics. The last is not a ninth component: it is any standard symbol with a diagonal strikethrough arrow, which is how a variable element is written.', 'A key of eight circuit schematic symbols, each drawn with its name beneath it. The battery is a long thin line beside a short thick one. The bulb is a circle with a cross inside it. The switch is a gap in the wire with a hinged arm lifted away from its contact. The capacitor is two equal parallel plates with a gap between them. The resistor is a zigzag. The ammeter is a circle marked A and the voltmeter a circle marked V. The last cell shows a resistor with a diagonal arrow struck through it: that arrow, over any standard symbol, is what makes the element variable, so it is a notation rather than a separate component. Illustrative data.', '', '', 'The diagonal arrow is a notation, not a ninth component: it makes any symbol variable.', true, null, '["Battery", "Bulb", "Switch", "Capacitor", "Resistor", "Ammeter (A)", "Voltmeter (V)", "Variable element"]'::jsonb, '{"columns": 4, "unit_note": "a diagonal arrow across any symbol marks a variable element", "symbol_sheet_check": true, "symbols": [{"glyph": "battery", "label": "Battery"}, {"glyph": "bulb", "label": "Bulb"}, {"glyph": "switch", "label": "Switch"}, {"glyph": "capacitor", "label": "Capacitor"}, {"glyph": "resistor", "label": "Resistor"}, {"glyph": "meter", "label": "Ammeter (A)", "letter": "A"}, {"glyph": "meter", "label": "Voltmeter (V)", "letter": "V"}, {"glyph": "resistor", "label": "Variable element", "variable": true, "base": "resistor"}]}'::jsonb, null, null, 'published', 'cramapple-authored; batch=phys-electric,phys2-equipotential,phys2-circuit-figures-2026-10-11', now())
on conflict (figure_id) do nothing;

-- 3. Where each figure is shown, resolved by natural key (protocol §6).
insert into app.figure_uses (figure_id, reference_entry_id, role)
select 'phys-electric-field-map', e.reference_entry_id, 'primary'
  from app.unit_reference_entries e
 where e.subject_key = 'ap_physics_2' and e.kind = 'diagram'
   and e.title = 'Electric field map and field line diagram' and e.status = 'published'
on conflict (figure_id, reference_entry_id) where reference_entry_id is not null do nothing;
insert into app.figure_uses (figure_id, reference_entry_id, role)
select 'phys-electric-field-map', e.reference_entry_id, 'secondary'
  from app.unit_reference_entries e
 where e.subject_key = 'ap_physics_c_em' and e.kind = 'diagram'
   and e.title = 'Electric field map and field line diagram' and e.status = 'published'
on conflict (figure_id, reference_entry_id) where reference_entry_id is not null do nothing;
insert into app.figure_uses (figure_id, reference_entry_id, role)
select 'phys2-equipotential-map', e.reference_entry_id, 'primary'
  from app.unit_reference_entries e
 where e.subject_key = 'ap_physics_2' and e.kind = 'diagram'
   and e.title = 'Equipotential (isoline) map' and e.status = 'published'
on conflict (figure_id, reference_entry_id) where reference_entry_id is not null do nothing;
insert into app.figure_uses (figure_id, reference_entry_id, role)
select 'phys2-circuit-symbols', e.reference_entry_id, 'primary'
  from app.unit_reference_entries e
 where e.subject_key = 'ap_physics_2' and e.kind = 'diagram'
   and e.title = 'Circuit schematic symbols' and e.status = 'published'
on conflict (figure_id, reference_entry_id) where reference_entry_id is not null do nothing;

-- 4. Guards: no dead figure, and every entry this batch covers got its figures.
do $$
declare v_dead text; v_n int;
begin
  select string_agg(f.figure_id, ', ') into v_dead
    from app.figures f left join app.figure_uses u on u.figure_id = f.figure_id
   where f.figure_id in ('phys-electric-field-map', 'phys2-equipotential-map', 'phys2-circuit-symbols') and u.figure_id is null;
  if v_dead is not null then
    raise exception 'figures with no use, refusing to ship dead rows: %', v_dead;
  end if;
  select count(*) into v_n from app.figures where figure_id in ('phys-electric-field-map', 'phys2-equipotential-map', 'phys2-circuit-symbols');
  if v_n <> 3 then
    raise exception 'expected 3 figures, found %', v_n;
  end if;
end $$;

commit;
